// Multiple-BFS based estimation of the graph radii (vertex eccentricities).
//
// 64 breadth-first searches are run simultaneously from 64 sampled source
// vertices; the set of sources that have reached a vertex is stored as a
// bitmask in a single 64-bit word (Visited/NextVisited).  A vertex's radii
// value is the last round in which its bitmask grew, i.e. the distance to the
// furthest sampled source that reaches it.  The maximum over all vertices is
// therefore a lower-bound estimate of the graph's diameter/radius.
#include "ligra.h"

// Atomically do a bitwise-OR of *a with b and store the result in location a.
// utils.h provides CAS/writeMin/writeAdd but no writeOr, so define it here.
template <class ET>
inline void writeOr(ET *a, ET b) {
  volatile ET newV, oldV;
  do {oldV = *a; newV = oldV | b;}
  while ((oldV != newV) && !CAS(a, oldV, newV));
}

struct Radii_F {
  intE round;
  intE* radii;
  long* Visited, *NextVisited;
  Radii_F(long* _Visited, long* _NextVisited, intE* _radii, intE _round) :
    Visited(_Visited), NextVisited(_NextVisited), radii(_radii), round(_round)
  {}
  //Update propagates the bitmask of s into the bitmask of d.  Returns 1 (i.e.
  //puts d on the next frontier) only the first time d's mask grows in a round.
  inline bool update (uintE s, uintE d) {
    long toWrite = Visited[d] | Visited[s];
    if(Visited[d] != toWrite) {
      NextVisited[d] |= toWrite;
      if(radii[d] != round) { radii[d] = round; return 1; }
    }
    return 0;
  }
  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
    long toWrite = Visited[d] | Visited[s];
    if(Visited[d] != toWrite) {
      writeOr(&NextVisited[d],toWrite);
      intE oldRadii = radii[d];
      //only one of the concurrent updaters wins the CAS and returns d
      if(oldRadii != round) return CAS(&radii[d],oldRadii,round);
    }
    return 0;
  }
  //all vertices are candidates for having their bitmask grow
  inline bool cond (uintE d) { return cond_true(d); }
};

//function passed to vertex map to sync NextVisited and Visited
struct Radii_Vertex_F {
  long* Visited, *NextVisited;
  Radii_Vertex_F(long* _Visited, long* _NextVisited) :
    Visited(_Visited), NextVisited(_NextVisited) {}
  inline bool operator () (uintE i) {
    Visited[i] = NextVisited[i];
    return 1;
  }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  long n = GA.n;
  intE* radii = newA(intE,n);
  long* Visited = newA(long,n);
  long* NextVisited = newA(long,n);
  {parallel_for(long i=0;i<n;i++) {
    radii[i] = -1;
    Visited[i] = NextVisited[i] = 0;
    }}
  long sampleSize = min(n,(long)64);
  uintE* starts = newA(uintE,sampleSize);

  {parallel_for(ulong i=0;i<sampleSize;i++) { //initial set of sampled sources
    uintE v = hashInt(i) % n;
    radii[v] = 0;
    starts[i] = v;
    NextVisited[v] = (long) 1<<i;   //source i owns bit i of the mask
    }}

  vertexSubset Frontier(n,sampleSize,starts); //initial frontier of size 64

  long round = 0;
  while(!Frontier.isEmpty()) {
    round++;
    //publish last round's bitmasks before reading them in the edgeMap
    vertexMap(Frontier, Radii_Vertex_F(Visited,NextVisited));
    //remove_duplicates: a vertex may be reached from several frontier vertices
    vertexSubset output =
      edgeMap(GA, Frontier, Radii_F(Visited,NextVisited,radii,round),
              GA.m/20, remove_duplicates);
    Frontier.del();
    Frontier = output; //set new frontier
  }
  Frontier.del();

  //the estimated radius is the largest distance recorded by any BFS
  intE maxRadii = sequence::reduce<intE>(radii,(intT)n,maxF<intE>());
  cout << "Radii rounds: " << round << endl;
  cout << "Radii max: " << maxRadii << endl;

  free(radii); free(Visited); free(NextVisited);
}
